function renderSheet(items) {
  const escape = (value) =>
    String(value ?? "").replace(
      /[&<>"']/g,
      (char) =>
        ({
          "&": "&amp;",
          "<": "&lt;",
          ">": "&gt;",
          '"': "&quot;",
          "'": "&#39;",
        })[char],
    );
  const [headings = [], ...rows] = items[0]?.json?.cells ?? [];
  const table = headings.length
    ? "<table><thead><tr>" +
      headings.map((value) => '<th scope="col">' + escape(value) + "</th>").join("") +
      "</tr></thead><tbody>" +
      rows
        .map(
          (row) =>
            "<tr>" +
            headings.map((_, index) => "<td>" + escape(row[index]) + "</td>").join("") +
            "</tr>",
        )
        .join("") +
      "</tbody></table>"
    : "";
  const empty = rows.length && headings.length ? "" : "<p>No rows in this range.</p>";
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; form-action 'none'; base-uri 'none'">
<title>Google Sheets Table</title>
<style>
body{font:1rem/1.5 system-ui,sans-serif;margin:0;color:#172233;background:#f7f9fc}
main{max-width:75rem;margin:auto;padding:clamp(1rem,4vw,3rem)}
.table{overflow:auto}
table{border-collapse:collapse;width:100%;background:#fff}
th,td{border:1px solid #d8e0eb;padding:.6rem .8rem;text-align:start;white-space:pre-wrap}
th{background:#e7edf7}
</style>
</head>
<body><main><h1>Google Sheets Table</h1><div class="table">${table}</div>${empty}</main></body>
</html>`;
}
return [{ json: { html: renderSheet($input.all()) } }];
